@import "tailwindcss";
@import "tw-animate-css";

@custom-variant dark (@media (prefers-color-scheme: dark));

/* shadcn/ui's colours, from Amber Notes' tokens (they switch for dark mode by themselves). */
:root {
  --radius: 0.75rem;
  --background: var(--amber-bg);
  --foreground: var(--amber-text);
  --card: var(--amber-surface);
  --card-foreground: var(--amber-text);
  --popover: var(--amber-bg);
  --popover-foreground: var(--amber-text);
  --primary: var(--amber-accent);
  --primary-foreground: var(--amber-on-accent);
  --secondary: var(--amber-fill);
  --secondary-foreground: var(--amber-text);
  --muted: var(--amber-fill);
  --muted-foreground: var(--amber-text-secondary);
  --accent: var(--amber-fill);
  --accent-foreground: var(--amber-text);
  --destructive: var(--amber-danger);
  --border: var(--amber-separator);
  --input: var(--amber-field-border);
  --ring: var(--amber-accent);
  --chart-1: var(--amber-accent);
  --chart-2: #3f8f6b;
  --chart-3: #4b74c9;
  --chart-4: #b5579a;
  --chart-5: #8a6d3b;
}

/* Lift's own colours: one per muscle (equipment glyphs, the muscle bars), and the set types. */
:root {
  --c-red: #D9475E; --c-blue: #3C78C8; --c-violet: #8A5CC8; --c-teal: #2A9A8A; --c-pink: #C94F94; --c-olive: #7C8A24; --c-amber: #D96A06; --c-green: #3E9A4C; --c-brown: #9A6A3A; --c-rose: #D06A6A; --c-sky: #3A9AC8;
  --ok: #2E9E5B; --warm: #C98A12; --drop: #7A5BD6; --fail: #D64545;
}
@media (prefers-color-scheme: dark) {
  :root { --c-red: #FF7A8E; --c-blue: #7DAAF0; --c-violet: #B98CF0; --c-teal: #4FD1BC; --c-pink: #F07DC0; --c-olive: #B9C95A; --c-amber: #F4AD33; --c-green: #6CD17C; --c-brown: #C9A57F; --c-rose: #F59A9A; --c-sky: #6FC2F0; --ok: #4CD38A; --warm: #F2C04A; --drop: #A58BFF; --fail: #FF6B6B; }
}
/* Sonner is full width on phones; with its side offsets that is wider than the screen. */
@media (max-width: 600px) { [data-sonner-toaster] { width: auto !important; } }
@keyframes tickpop { 40% { transform: scale(1.15); } }

@theme inline {
  --color-ok: var(--ok);
  --color-warm: var(--warm);
  --color-drop: var(--drop);
  --color-fail: var(--fail);
  --font-sans: var(--amber-font);
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --color-chart-1: var(--chart-1);
  --color-chart-2: var(--chart-2);
  --color-chart-3: var(--chart-3);
  --color-chart-4: var(--chart-4);
  --color-chart-5: var(--chart-5);
  --radius-sm: calc(var(--radius) - 4px);
  --radius-md: calc(var(--radius) - 2px);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) + 4px);
}

@layer base {
  * { @apply border-border outline-ring/50; }
  body { @apply bg-background text-foreground; }
}

