          <Bar dataKey="v" radius={[3, 3, 0, 0]} isAnimationActive={false} shape={(p: any) => <rect x={p.x} y={p.y} width={p.width} height={Math.max(1, p.height)} rx={3} fill="var(--primary)" fillOpacity={p.payload.dim ? 0.35 : 1} />} />
        </BarChart>
      </ResponsiveContainer>
    </div>
  )
}

